#requires -Version 5.1
param([string]$OutputDirectory = $PSScriptRoot)
$ErrorActionPreference = 'Stop'
$AegisPayloadBase64 = ''
$AegisExpectedPayloadSha256 = 'b746ac81d25b05399cd8b359f022f889fe5a52ac0345adad39594cdaaa7bc2f4'
$AegisBytes = [Convert]::FromBase64String($AegisPayloadBase64)
$AegisSha = [Security.Cryptography.SHA256]::Create()
try { $AegisActualHash = ([BitConverter]::ToString($AegisSha.ComputeHash($AegisBytes))).Replace('-', '').ToLowerInvariant() }
finally { $AegisSha.Dispose() }
if ($AegisActualHash -ne $AegisExpectedPayloadSha256) { throw 'COLLECTOR_PAYLOAD_HASH_MISMATCH. No remote command executed.' }
$AegisRailway = Get-Command railway -ErrorAction SilentlyContinue
if (-not $AegisRailway) { throw 'RAILWAY_CLI_UNAVAILABLE. Use the existing authenticated Railway CLI, then rerun.' }
function Invoke-AegisRailway {
    param([string]$Arguments, [string]$InputText = '', [int]$TimeoutMs = 15000)
    $AegisInfo = New-Object Diagnostics.ProcessStartInfo
    $AegisInfo.UseShellExecute = $false
    $AegisInfo.CreateNoWindow = $true
    $AegisInfo.RedirectStandardInput = $true
    $AegisInfo.RedirectStandardOutput = $true
    $AegisInfo.RedirectStandardError = $true
    $AegisPath = $AegisRailway.Source
    if ($AegisPath -match '\.(cmd|bat)$') {
        $AegisInfo.FileName = $env:COMSPEC
        $AegisInfo.Arguments = '/d /s /c ""' + $AegisPath + '" ' + $Arguments + '"'
    } else {
        $AegisInfo.FileName = $AegisPath
        $AegisInfo.Arguments = $Arguments
    }
    $AegisProcess = New-Object Diagnostics.Process
    $AegisProcess.StartInfo = $AegisInfo
    try {
        if (-not $AegisProcess.Start()) { throw 'RAILWAY_PROCESS_START_FAILED' }
        $AegisOutTask = $AegisProcess.StandardOutput.ReadToEndAsync()
        $AegisErrTask = $AegisProcess.StandardError.ReadToEndAsync()
        if ($InputText) { $AegisProcess.StandardInput.WriteLine($InputText) }
        $AegisProcess.StandardInput.Close()
        if (-not $AegisProcess.WaitForExit($TimeoutMs)) {
            try { if ($env:OS -eq 'Windows_NT') { & taskkill.exe /PID $AegisProcess.Id /T /F 2>$null | Out-Null } else { $AegisProcess.Kill($true) } } catch {}
            throw 'RAILWAY_PROCESS_DEADLINE_EXCEEDED. No complete evidence; do not treat this as success.'
        }
        $AegisResult = [pscustomobject]@{ Code = $AegisProcess.ExitCode; Out = $AegisOutTask.GetAwaiter().GetResult() }
        # Read and discard transport diagnostics: never print or persist authentication output.
        $null = $AegisErrTask.GetAwaiter().GetResult()
        return $AegisResult
    } finally { $AegisProcess.Dispose() }
}
$AegisAuth = Invoke-AegisRailway -Arguments 'whoami --json'
if ($AegisAuth.Code -ne 0) { throw 'RAILWAY_AUTHENTICATION_REQUIRED. Complete railway login in your own terminal, then rerun.' }
$AegisBootstrap = 'const b=Buffer.from("' + $AegisPayloadBase64 + '","base64");if(require("crypto").createHash("sha256").update(b).digest("hex")!=="' + $AegisExpectedPayloadSha256 + '")process.exit(2);const m={exports:{}};new Function("require","module","exports",b.toString("utf8"))(require,m,m.exports);m.exports.runCli();'
Write-Host ('Collector SHA-256 verified: ' + $AegisActualHash)
Write-Host 'Running read-only metadata collection in the existing Railway BACKEND shell (60-second collector / 90-second transport limit).'
$AegisRemote = Invoke-AegisRailway -Arguments 'ssh --project 0233d8e5-8437-4d94-ad0c-3f24deb1902e --environment aa887588-a793-47b7-b789-df297f78ef8d --service 75a4edb0-86fb-4fb6-b7d7-3f88880503ec -- node --no-warnings' -InputText $AegisBootstrap -TimeoutMs 90000
$AegisStart = 'AEGIS_READONLY_EVIDENCE_BEGIN'
$AegisEnd = 'AEGIS_READONLY_EVIDENCE_END'
$AegisFirst = $AegisRemote.Out.IndexOf($AegisStart, [StringComparison]::Ordinal)
$AegisLast = $AegisRemote.Out.IndexOf($AegisEnd, [StringComparison]::Ordinal)
if ($AegisFirst -lt 0 -or $AegisLast -le $AegisFirst) { throw 'NO_COMPLETE_COLLECTOR_RECORD. Verify existing Railway SSH access to the named backend; do not send raw transport output or credentials.' }
$AegisJson = $AegisRemote.Out.Substring($AegisFirst + $AegisStart.Length, $AegisLast - $AegisFirst - $AegisStart.Length).Trim()
$AegisParsed = $AegisJson | ConvertFrom-Json
if ($AegisParsed.collectorVersion -ne 2 -or $AegisParsed.productionMutations -ne $false) { throw 'UNEXPECTED_COLLECTOR_RECORD' }
if (-not (Test-Path -LiteralPath $OutputDirectory -PathType Container)) { throw 'OUTPUT_DIRECTORY_UNAVAILABLE' }
$AegisFile = Join-Path $OutputDirectory ('AEGIS-Production-Readonly-' + [DateTime]::UtcNow.ToString('yyyyMMddTHHmmssfffZ') + '.json')
if (Test-Path -LiteralPath $AegisFile) { throw 'OUTPUT_ALREADY_EXISTS. Preserve it; rerun only after reviewing the prior result.' }
$AegisUtf8 = New-Object Text.UTF8Encoding($false)
[IO.File]::WriteAllText($AegisFile, $AegisJson, $AegisUtf8)
Write-Host ('Evidence saved: ' + $AegisFile)
Write-Host ('Collector result: ' + $AegisParsed.status)
Write-Host 'Return ONLY this JSON, plus the existing backup schedule/retention and last successful restore evidence. Do not send credentials, URLs with passwords, private keys or operational rows.'
if ($AegisRemote.Code -ne 0 -or $AegisParsed.status -eq 'INCOMPLETE_BLOCKED') { exit 2 }
